    case "top":
      break;
    case "bottom":
      child.y += dh;
      break;
    case "center":
      child.y += dh / 2;
      break;
    case "top-bottom":
      child.height = Math.max(MIN_SIZE, child.height + dh);
      break;
    case "scale":
      child.y *= sy;
      child.height = Math.max(MIN_SIZE, child.height * sy);
      break;
  }
