  if ((node.type === "frame" || node.type === "component") && node.clipContent) {
    defs.push(
      `<clipPath id="clip-${node.id}"><rect width="${node.width}" height="${node.height}" rx="${"cornerRadius" in node ? node.cornerRadius.tl : 0}"/></clipPath>`,
    );
  }
  for (const p of node.fills) {
    if (p.type !== "solid") defs.push(gradientDef(p, node.id));
  }

