    const last = node.points[node.points.length - 1];
    if (last && first) {
      d += ` C ${last.x + last.handleOut.x} ${last.y + last.handleOut.y}, ${first.x + first.handleIn.x} ${first.y + first.handleIn.y}, ${first.x} ${first.y} Z`;
