import { colorToCss } from "../core/color";
import { isParent } from "../core/factories";
import {
  ellipsePolygon,
  flattenPath,
  regularPolygon,
  roundRectPath,
  starPolygon,
} from "../core/geometry";
import { activePage, worldAABB } from "../core/scene";
import { fontCss, lineOffsetX, wrapLines } from "../core/text-layout";
import type { Camera, Document, Effect, SceneNode } from "../core/types";
import { GRID_MAJOR, GRID_MINOR, RULER_SIZE } from "../core/types";
import { applyPaint, strokeOffset } from "./paints";

const imageCache = new Map<string, HTMLImageElement>();

export function preloadImage(src: string): HTMLImageElement | null {
  const hit = imageCache.get(src);
  if (hit && hit.complete) return hit;
  if (hit) return null;
  const img = new Image();
  img.decoding = "async";
  img.src = src;
  imageCache.set(src, img);
  return img.complete ? img : null;
}

export interface RenderView {
  width: number;
  height: number;
  rulers: boolean;
  grid: boolean;
  pixelPreview: boolean;
}

function cameraTransform(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  view: RenderView,
): void {
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  ctx.setTransform(camera.zoom, 0, 0, camera.zoom, ox + w / 2 - camera.x * camera.zoom, oy + h / 2 - camera.y * camera.zoom);
}

export function drawGrid(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  view: RenderView,
): void {
  if (!view.grid) return;
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  const worldLeft = camera.x - w / 2 / camera.zoom;
  const worldTop = camera.y - h / 2 / camera.zoom;
  const worldRight = camera.x + w / 2 / camera.zoom;
  const worldBottom = camera.y + h / 2 / camera.zoom;

  const minor = camera.zoom < 0.35 ? GRID_MAJOR : GRID_MINOR;
  const major = minor * 10;

  ctx.save();
  cameraTransform(ctx, camera, view);
  ctx.lineWidth = 1 / camera.zoom;

  const draw = (step: number, color: string) => {
    ctx.strokeStyle = color;
    ctx.beginPath();
    const x0 = Math.floor(worldLeft / step) * step;
    for (let x = x0; x <= worldRight; x += step) {
      ctx.moveTo(x, worldTop);
      ctx.lineTo(x, worldBottom);
    }
    const y0 = Math.floor(worldTop / step) * step;
    for (let y = y0; y <= worldBottom; y += step) {
      ctx.moveTo(worldLeft, y);
      ctx.lineTo(worldRight, y);
    }
    ctx.stroke();
  };

  draw(minor, "rgba(255,255,255,0.035)");
  draw(major, "rgba(255,255,255,0.07)");
  ctx.restore();
}

function viewportWorld(camera: Camera, view: RenderView): { minX: number; minY: number; maxX: number; maxY: number } {
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  const hw = w / 2 / camera.zoom;
  const hh = h / 2 / camera.zoom;
  return { minX: camera.x - hw, minY: camera.y - hh, maxX: camera.x + hw, maxY: camera.y + hh };
}

export function drawScene(
  ctx: CanvasRenderingContext2D,
  doc: Document,
  camera: Camera,
  view: RenderView,
): void {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = "#2c2c2c";
  ctx.fillRect(0, 0, view.width, view.height);
  drawGrid(ctx, camera, view);

  const vp = viewportWorld(camera, view);
  ctx.save();
  cameraTransform(ctx, camera, view);
  if (view.pixelPreview && camera.zoom >= 2) {
    ctx.imageSmoothingEnabled = false;
  } else {
    ctx.imageSmoothingEnabled = true;
  }

  const page = activePage(doc);
  const walk = (ids: string[]) => {
    for (const id of ids) {
      const node = doc.nodes[id];
      if (!node || !node.visible) continue;
      const aabb = worldAABB(doc, id);
      if (aabb.maxX < vp.minX || aabb.maxY < vp.minY || aabb.minX > vp.maxX || aabb.minY > vp.maxY) {
        continue;
      }
      drawNode(ctx, doc, node, camera.zoom);
    }
  };
  walk(page.children);
  ctx.restore();
}

function drawNode(ctx: CanvasRenderingContext2D, doc: Document, node: SceneNode, zoom: number): void {
  ctx.save();
  ctx.translate(node.x + node.width / 2, node.y + node.height / 2);
  ctx.rotate((node.rotation * Math.PI) / 180);
  ctx.translate(-node.width / 2, -node.height / 2);
  ctx.globalAlpha *= node.opacity;
  ctx.globalCompositeOperation = node.blendMode;

  const blur = node.effects.find((e): e is Extract<Effect, { type: "layer-blur" }> => e.type === "layer-blur" && e.visible);
  if (blur && blur.radius > 0) ctx.filter = `blur(${blur.radius}px)`;

  const drop = node.effects.find((e) => e.type === "drop-shadow" && e.visible);
  if (drop && drop.type === "drop-shadow") {
    ctx.save();
    ctx.shadowColor = colorToCss(drop.color);
    ctx.shadowBlur = drop.blur;
    ctx.shadowOffsetX = drop.x;
    ctx.shadowOffsetY = drop.y;
    fillShape(ctx, node);
    ctx.restore();
  } else {
    fillShape(ctx, node);
  }

  strokeShape(ctx, node);

  if (node.type === "text") drawText(ctx, node);
  if (node.type === "image") drawImage(ctx, node);

  const inner = node.effects.find((e) => e.type === "inner-shadow" && e.visible);
  if (inner && inner.type === "inner-shadow") drawInnerShadow(ctx, node, inner);

  if (isParent(node)) {
    const clip = (node.type === "frame" || node.type === "component") && node.clipContent;
    if (clip) {
      ctx.beginPath();
      pathFor(ctx, node);
      ctx.clip();
    }
    for (const cid of node.children) {
      const child = doc.nodes[cid];
      if (child && child.visible) drawNode(ctx, doc, child, zoom);
    }
  }

  ctx.filter = "none";
  ctx.restore();
}

function pathFor(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  ctx.beginPath();
  switch (node.type) {
    case "ellipse":
      ctx.ellipse(node.width / 2, node.height / 2, node.width / 2, node.height / 2, 0, 0, Math.PI * 2);
      break;
    case "polygon": {
      const pts = regularPolygon(node.sides, node.width, node.height);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      ctx.closePath();
      break;
    }
    case "star": {
      const pts = starPolygon(node.points, node.innerRatio, node.width, node.height);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      ctx.closePath();
      break;
    }
    case "path": {
      const pts = flattenPath(node.points, node.closed);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      if (node.closed) ctx.closePath();
      break;
    }
    case "line":
      ctx.moveTo(0, node.height / 2);
      ctx.lineTo(node.width, node.height / 2);
      break;
    default: {
      const r =
        "cornerRadius" in node
          ? node.cornerRadius
          : { tl: 0, tr: 0, br: 0, bl: 0 };
      roundRectPath(ctx, 0, 0, node.width, node.height, r);
    }
  }
}

function fillShape(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  if (node.type === "line" || node.type === "text" || node.fills.length === 0) return;
  for (const paint of node.fills) {
    pathFor(ctx, node);
    ctx.fillStyle = applyPaint(ctx, paint, node.width, node.height);
    ctx.fill();
  }
}

function strokeShape(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  for (const stroke of node.strokes) {
    const o = strokeOffset(stroke, node.width, node.height);
    ctx.save();
    ctx.translate(o.x, o.y);
    ctx.scale(o.w / node.width || 1, o.h / node.height || 1);
    pathFor(ctx, node);
    ctx.strokeStyle = applyPaint(ctx, stroke.paint, node.width, node.height);
    ctx.lineWidth = stroke.thickness * (node.width / (o.w || 1));
    ctx.lineCap = stroke.cap;
    ctx.lineJoin = stroke.join;
    ctx.setLineDash(stroke.dash);
    ctx.stroke();
    ctx.restore();
  }
}

function drawText(ctx: CanvasRenderingContext2D, node: Extract<SceneNode, { type: "text" }>): void {
  const t = node.text;
  ctx.font = fontCss(t);
  ctx.fillStyle = colorToCss(t.color);
  ctx.textBaseline = "alphabetic";
  const lines = wrapLines(node.characters, node.width, t.letterSpacing, (s) => ctx.measureText(s).width);
  const lh = t.fontSize * t.lineHeight;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, node.width, node.height);
  ctx.clip();
  lines.forEach((line, i) => {
    const x = lineOffsetX(t.align, line.width, node.width);
    const y = (i + 0.85) * lh;
    if (t.letterSpacing === 0) {
      ctx.fillText(line.text, x, y);
    } else {
      let cx = x;
      for (const ch of line.text) {
        ctx.fillText(ch, cx, y);
        cx += ctx.measureText(ch).width + t.letterSpacing;
      }
    }
  });
  ctx.restore();
}

function drawImage(ctx: CanvasRenderingContext2D, node: Extract<SceneNode, { type: "image" }>): void {
  const img = preloadImage(node.src);
  pathFor(ctx, node);
  ctx.save();
  ctx.clip();
  if (!img) {
    ctx.fillStyle = "#3a3a3a";
    ctx.fillRect(0, 0, node.width, node.height);
    ctx.restore();
    return;
  }
  const iw = img.naturalWidth || img.width;
  const ih = img.naturalHeight || img.height;
  if (node.fit === "fill") {
    ctx.drawImage(img, 0, 0, node.width, node.height);
  } else {
    const scale =
      node.fit === "fit" ? Math.min(node.width / iw, node.height / ih) : Math.max(node.width / iw, node.height / ih);
    const dw = iw * scale;
    const dh = ih * scale;
    ctx.drawImage(img, (node.width - dw) / 2, (node.height - dh) / 2, dw, dh);
  }
  ctx.restore();
}

function drawInnerShadow(
  ctx: CanvasRenderingContext2D,
  node: SceneNode,
  effect: Extract<Effect, { type: "inner-shadow" }>,
): void {
  ctx.save();
  pathFor(ctx, node);
  ctx.clip();
  ctx.shadowColor = colorToCss(effect.color);
  ctx.shadowBlur = effect.blur;
  ctx.shadowOffsetX = effect.x;
  ctx.shadowOffsetY = effect.y;
  ctx.strokeStyle = colorToCss(effect.color);
  ctx.lineWidth = 20 + effect.spread;
  pathFor(ctx, node);
  ctx.stroke();
  ctx.restore();
}

void ellipsePolygon;

import { colorToCss, GUIDE_PINK, SELECTION } from "../core/color";
import { apply, localCorners, nodeLocalMatrix } from "../core/geometry";
import { worldAABB, worldMatrixOf } from "../core/scene";
import type { AABB, Camera, Document, Guide, Handle, NodeId, PathPoint, SceneNode, Vec2 } from "../core/types";
import { HANDLE_SIZE, ROTATE_HANDLE_OFFSET, RULER_SIZE } from "../core/types";
import { worldToScreen } from "../input/camera";

const HANDLES: Handle[] = ["nw", "n", "ne", "e", "se", "s", "sw", "w"];

export function drawOverlay(
  ctx: CanvasRenderingContext2D,
  doc: Document,
  camera: Camera,
  view: { width: number; height: number; rulers: boolean },
  opts: {
    selection: NodeId[];
    hoveredId: NodeId | null;
    marquee: AABB | null;
    lasso: Vec2[] | null;
    guides: Guide[];
    penDraft: PathPoint[] | null;
    prototypeFrom: NodeId | null;
    editingTextId: NodeId | null;
  },
): void {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.clearRect(0, 0, view.width, view.height);

  const toS = (x: number, y: number) => worldToScreen(x, y, camera, view.width, view.height, view.rulers);

  if (opts.hoveredId && !opts.selection.includes(opts.hoveredId)) {
    strokeNode(ctx, doc, opts.hoveredId, toS, "rgba(13,153,255,0.55)", 1);
  }

  for (const id of opts.selection) {
    if (id === opts.editingTextId) continue;
    strokeNode(ctx, doc, id, toS, colorToCss(SELECTION), 1.5);
    drawHandles(ctx, doc, id, toS, camera.zoom);
  }

  if (opts.selection.length > 1) {
    const boxes = opts.selection.map((id) => worldAABB(doc, id));
    const minX = Math.min(...boxes.map((b) => b.minX));
    const minY = Math.min(...boxes.map((b) => b.minY));
    const maxX = Math.max(...boxes.map((b) => b.maxX));
    const maxY = Math.max(...boxes.map((b) => b.maxY));
    const a = toS(minX, minY);
    const b = toS(maxX, maxY);
    ctx.strokeStyle = "rgba(13,153,255,0.35)";
    ctx.setLineDash([4, 4]);
    ctx.strokeRect(a.x, a.y, b.x - a.x, b.y - a.y);
    ctx.setLineDash([]);
  }

  for (const g of opts.guides) {
    ctx.strokeStyle = colorToCss(GUIDE_PINK);
    ctx.fillStyle = colorToCss(GUIDE_PINK);
    ctx.lineWidth = 1;
    if (g.axis === "x") {
      const p = toS(g.position, 0);
      ctx.beginPath();
      ctx.moveTo(p.x, 0);
      ctx.lineTo(p.x, view.height);
      ctx.stroke();
    } else {
      const p = toS(0, g.position);
      ctx.beginPath();
      ctx.moveTo(0, p.y);
      ctx.lineTo(view.width, p.y);
      ctx.stroke();
    }
    if (g.label) {
      const p = g.axis === "x" ? toS(g.position, camera.y) : toS(camera.x, g.position);
      ctx.font = "11px Inter, system-ui, sans-serif";
      const tw = ctx.measureText(g.label).width;
      ctx.fillStyle = colorToCss(GUIDE_PINK);
      ctx.fillRect(p.x - tw / 2 - 4, p.y - 8, tw + 8, 16);
      ctx.fillStyle = "#fff";
      ctx.fillText(g.label, p.x - tw / 2, p.y + 4);
    }
  }

  if (opts.marquee) {
    const a = toS(opts.marquee.minX, opts.marquee.minY);
    const b = toS(opts.marquee.maxX, opts.marquee.maxY);
    ctx.fillStyle = "rgba(13,153,255,0.12)";
    ctx.strokeStyle = colorToCss(SELECTION);
    ctx.fillRect(a.x, a.y, b.x - a.x, b.y - a.y);
    ctx.strokeRect(a.x, a.y, b.x - a.x, b.y - a.y);
  }

  if (opts.lasso && opts.lasso.length > 1) {
    ctx.beginPath();
    opts.lasso.forEach((p, i) => {
      const s = toS(p.x, p.y);
      if (i === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    });
    ctx.closePath();
    ctx.fillStyle = "rgba(13,153,255,0.08)";
    ctx.strokeStyle = colorToCss(SELECTION);
    ctx.setLineDash([6, 4]);
    ctx.fill();
    ctx.stroke();
    ctx.setLineDash([]);
  }

  if (opts.penDraft && opts.penDraft.length) {
    ctx.strokeStyle = colorToCss(SELECTION);
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    opts.penDraft.forEach((p, i) => {
      const s = toS(p.x, p.y);
      if (i === 0) ctx.moveTo(s.x, s.y);
      else ctx.lineTo(s.x, s.y);
    });
    ctx.stroke();
    for (const p of opts.penDraft) {
      const s = toS(p.x, p.y);
      ctx.fillRect(s.x - 3, s.y - 3, 6, 6);
      ctx.strokeRect(s.x - 3, s.y - 3, 6, 6);
    }
  }

  for (const link of doc.prototypeLinks) {
    const from = doc.nodes[link.fromId];
    const to = doc.nodes[link.toId];
    if (!from || !to) continue;
    const a = worldAABB(doc, from.id);
    const b = worldAABB(doc, to.id);
    const p1 = toS((a.minX + a.maxX) / 2, (a.minY + a.maxY) / 2);
    const p2 = toS((b.minX + b.maxX) / 2, (b.minY + b.maxY) / 2);
    ctx.strokeStyle = "#7c5cbf";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.bezierCurveTo((p1.x + p2.x) / 2, p1.y, (p1.x + p2.x) / 2, p2.y, p2.x, p2.y);
    ctx.stroke();
  }

  for (const c of doc.comments) {
    if (c.resolved) continue;
    const s = toS(c.x, c.y);
    ctx.fillStyle = "#7c5cbf";
    ctx.beginPath();
    ctx.arc(s.x, s.y, 10, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#fff";
    ctx.font = "700 10px Inter, system-ui";
    ctx.fillText("•", s.x - 3, s.y + 4);
  }

  if (view.rulers) drawRulers(ctx, camera, view, opts.selection, doc);
}

function strokeNode(
  ctx: CanvasRenderingContext2D,
  doc: Document,
  id: NodeId,
  toS: (x: number, y: number) => Vec2,
  color: string,
  width: number,
): void {
  const node = doc.nodes[id];
  if (!node) return;
  const m = worldMatrixOf(doc, id);
  const pts = localCorners(node.width, node.height).map((p) => {
    const w = apply(m, p);
    return toS(w.x, w.y);
  });
  ctx.beginPath();
  pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
  ctx.closePath();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.stroke();
}

function handleLocal(node: SceneNode, handle: Handle): Vec2 {
  const w = node.width;
  const h = node.height;
  switch (handle) {
    case "nw":
      return { x: 0, y: 0 };
    case "n":
      return { x: w / 2, y: 0 };
    case "ne":
      return { x: w, y: 0 };
    case "e":
      return { x: w, y: h / 2 };
    case "se":
      return { x: w, y: h };
    case "s":
      return { x: w / 2, y: h };
    case "sw":
      return { x: 0, y: h };
    case "w":
      return { x: 0, y: h / 2 };
  }
}

function drawHandles(
  ctx: CanvasRenderingContext2D,
  doc: Document,
  id: NodeId,
  toS: (x: number, y: number) => Vec2,
  _zoom: number,
): void {
  const node = doc.nodes[id];
  if (!node) return;
  const m = worldMatrixOf(doc, id);
  const hs = HANDLE_SIZE;
  ctx.fillStyle = "#fff";
  ctx.strokeStyle = colorToCss(SELECTION);
  ctx.lineWidth = 1;
  for (const handle of HANDLES) {
    const w = apply(m, handleLocal(node, handle));
    const s = toS(w.x, w.y);
    ctx.fillRect(s.x - hs / 2, s.y - hs / 2, hs, hs);
    ctx.strokeRect(s.x - hs / 2, s.y - hs / 2, hs, hs);
  }
  const top = apply(m, { x: node.width / 2, y: 0 });
  const topS = toS(top.x, top.y);
  const rot = { x: topS.x, y: topS.y - ROTATE_HANDLE_OFFSET };
  ctx.beginPath();
  ctx.moveTo(topS.x, topS.y);
  ctx.lineTo(rot.x, rot.y);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(rot.x, rot.y, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
}

export function hitHandle(
  doc: Document,
  id: NodeId,
  screen: Vec2,
  camera: Camera,
  view: { width: number; height: number; rulers: boolean },
): Handle | "rotate" | null {
  const node = doc.nodes[id];
  if (!node) return null;
  const m = worldMatrixOf(doc, id);
  const toS = (x: number, y: number) => worldToScreen(x, y, camera, view.width, view.height, view.rulers);
  const slop = HANDLE_SIZE;
  for (const handle of HANDLES) {
    const w = apply(m, handleLocal(node, handle));
    const s = toS(w.x, w.y);
    if (Math.abs(s.x - screen.x) <= slop && Math.abs(s.y - screen.y) <= slop) return handle;
  }
  const top = apply(m, { x: node.width / 2, y: 0 });
  const topS = toS(top.x, top.y);
  const rot = { x: topS.x, y: topS.y - ROTATE_HANDLE_OFFSET };
  if (Math.hypot(rot.x - screen.x, rot.y - screen.y) <= 8) return "rotate";
  return null;
}

function drawRulers(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  view: { width: number; height: number; rulers: boolean },
  selection: NodeId[],
  doc: Document,
): void {
  const r = RULER_SIZE;
  ctx.fillStyle = "#2a2a2a";
  ctx.fillRect(0, 0, view.width, r);
  ctx.fillRect(0, 0, r, view.height);
  ctx.fillStyle = "#1f1f1f";
  ctx.fillRect(0, 0, r, r);
  ctx.strokeStyle = "rgba(255,255,255,0.08)";
  ctx.beginPath();
  ctx.moveTo(0, r);
  ctx.lineTo(view.width, r);
  ctx.moveTo(r, 0);
  ctx.lineTo(r, view.height);
  ctx.stroke();

  const step = niceStep(50 / camera.zoom);
  const ox = r;
  const oy = r;
  const w = view.width - ox;
  const h = view.height - oy;
  const worldLeft = camera.x - w / 2 / camera.zoom;
  const worldTop = camera.y - h / 2 / camera.zoom;
  ctx.fillStyle = "rgba(255,255,255,0.45)";
  ctx.font = "9px Inter, system-ui";
  ctx.strokeStyle = "rgba(255,255,255,0.18)";

  const x0 = Math.floor(worldLeft / step) * step;
  ctx.beginPath();
  for (let x = x0; x < worldLeft + w / camera.zoom; x += step) {
    const s = worldToScreen(x, 0, camera, view.width, view.height, true);
    ctx.moveTo(s.x, r);
    ctx.lineTo(s.x, r - 6);
    ctx.fillText(String(Math.round(x)), s.x + 2, 12);
  }
  const y0 = Math.floor(worldTop / step) * step;
  for (let y = y0; y < worldTop + h / camera.zoom; y += step) {
    const s = worldToScreen(0, y, camera, view.width, view.height, true);
    ctx.moveTo(r, s.y);
    ctx.lineTo(r - 6, s.y);
    ctx.save();
    ctx.translate(10, s.y - 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText(String(Math.round(y)), 0, 0);
    ctx.restore();
  }
  ctx.stroke();

  if (selection.length) {
    const b = worldAABB(doc, selection[0]!);
    ctx.fillStyle = "rgba(13,153,255,0.35)";
    const a = worldToScreen(b.minX, b.minY, camera, view.width, view.height, true);
    const c = worldToScreen(b.maxX, b.maxY, camera, view.width, view.height, true);
    ctx.fillRect(a.x, 0, Math.max(1, c.x - a.x), r);
    ctx.fillRect(0, a.y, r, Math.max(1, c.y - a.y));
  }
}

function niceStep(raw: number): number {
  const mag = 10 ** Math.floor(Math.log10(raw));
  const n = raw / mag;
  if (n < 2) return mag;
  if (n < 5) return 2 * mag;
  return 5 * mag;
}

void nodeLocalMatrix;

import { colorToCss } from "../core/color";
import { isParent } from "../core/factories";
import {
  ellipsePolygon,
  flattenPath,
  regularPolygon,
  roundRectPath,
  starPolygon,
} from "../core/geometry";
import { activePage, worldAABB } from "../core/scene";
import { fontCss, lineOffsetX, wrapLines } from "../core/text-layout";
import type { Camera, Document, Effect, SceneNode } from "../core/types";
import { GRID_MAJOR, GRID_MINOR, RULER_SIZE } from "../core/types";
import { applyPaint, strokeOffset } from "./paints";

const imageCache = new Map<string, HTMLImageElement>();

export function preloadImage(src: string): HTMLImageElement | null {
  const hit = imageCache.get(src);
  if (hit && hit.complete) return hit;
  if (hit) return null;
  const img = new Image();
  img.decoding = "async";
  img.src = src;
  imageCache.set(src, img);
  return img.complete ? img : null;
}

export interface RenderView {
  width: number;
  height: number;
  rulers: boolean;
  grid: boolean;
  pixelPreview: boolean;
}

function cameraTransform(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  view: RenderView,
): void {
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  ctx.setTransform(camera.zoom, 0, 0, camera.zoom, ox + w / 2 - camera.x * camera.zoom, oy + h / 2 - camera.y * camera.zoom);
}

export function drawGrid(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  view: RenderView,
): void {
  if (!view.grid) return;
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  const worldLeft = camera.x - w / 2 / camera.zoom;
  const worldTop = camera.y - h / 2 / camera.zoom;
  const worldRight = camera.x + w / 2 / camera.zoom;
  const worldBottom = camera.y + h / 2 / camera.zoom;

  const minor = camera.zoom < 0.35 ? GRID_MAJOR : GRID_MINOR;
  const major = minor * 10;

  ctx.save();
  cameraTransform(ctx, camera, view);
  ctx.lineWidth = 1 / camera.zoom;

  const draw = (step: number, color: string) => {
    ctx.strokeStyle = color;
    ctx.beginPath();
    const x0 = Math.floor(worldLeft / step) * step;
    for (let x = x0; x <= worldRight; x += step) {
      ctx.moveTo(x, worldTop);
      ctx.lineTo(x, worldBottom);
    }
    const y0 = Math.floor(worldTop / step) * step;
    for (let y = y0; y <= worldBottom; y += step) {
      ctx.moveTo(worldLeft, y);
      ctx.lineTo(worldRight, y);
    }
    ctx.stroke();
  };

  draw(minor, "rgba(255,255,255,0.035)");
  draw(major, "rgba(255,255,255,0.07)");
  ctx.restore();
}

function viewportWorld(camera: Camera, view: RenderView): { minX: number; minY: number; maxX: number; maxY: number } {
  const ox = view.rulers ? RULER_SIZE : 0;
  const oy = view.rulers ? RULER_SIZE : 0;
  const w = view.width - ox;
  const h = view.height - oy;
  const hw = w / 2 / camera.zoom;
  const hh = h / 2 / camera.zoom;
  return { minX: camera.x - hw, minY: camera.y - hh, maxX: camera.x + hw, maxY: camera.y + hh };
}

export function drawScene(
  ctx: CanvasRenderingContext2D,
  doc: Document,
  camera: Camera,
  view: RenderView,
): void {
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = "#2c2c2c";
  ctx.fillRect(0, 0, view.width, view.height);
  drawGrid(ctx, camera, view);

  const vp = viewportWorld(camera, view);
  ctx.save();
  cameraTransform(ctx, camera, view);
  if (view.pixelPreview && camera.zoom >= 2) {
    ctx.imageSmoothingEnabled = false;
  } else {
    ctx.imageSmoothingEnabled = true;
  }

  const page = activePage(doc);
  const walk = (ids: string[]) => {
    for (const id of ids) {
      const node = doc.nodes[id];
      if (!node || !node.visible) continue;
      const aabb = worldAABB(doc, id);
      if (aabb.maxX < vp.minX || aabb.maxY < vp.minY || aabb.minX > vp.maxX || aabb.minY > vp.maxY) {
        continue;
      }
      drawNode(ctx, doc, node, camera.zoom);
    }
  };
  walk(page.children);
  ctx.restore();
}

function drawNode(ctx: CanvasRenderingContext2D, doc: Document, node: SceneNode, zoom: number): void {
  ctx.save();
  ctx.translate(node.x + node.width / 2, node.y + node.height / 2);
  ctx.rotate((node.rotation * Math.PI) / 180);
  ctx.translate(-node.width / 2, -node.height / 2);
  ctx.globalAlpha *= node.opacity;
  ctx.globalCompositeOperation = node.blendMode;

  const blur = node.effects.find((e): e is Extract<Effect, { type: "layer-blur" }> => e.type === "layer-blur" && e.visible);
  if (blur && blur.radius > 0) ctx.filter = `blur(${blur.radius}px)`;

  const drop = node.effects.find((e) => e.type === "drop-shadow" && e.visible);
  if (drop && drop.type === "drop-shadow") {
    ctx.save();
    ctx.shadowColor = colorToCss(drop.color);
    ctx.shadowBlur = drop.blur;
    ctx.shadowOffsetX = drop.x;
    ctx.shadowOffsetY = drop.y;
    fillShape(ctx, node);
    ctx.restore();
  } else {
    fillShape(ctx, node);
  }

  strokeShape(ctx, node);

  if (node.type === "text") drawText(ctx, node);
  if (node.type === "image") drawImage(ctx, node);

  const inner = node.effects.find((e) => e.type === "inner-shadow" && e.visible);
  if (inner && inner.type === "inner-shadow") drawInnerShadow(ctx, node, inner);

  if (isParent(node)) {
    const clip = (node.type === "frame" || node.type === "component") && node.clipContent;
    if (clip) {
      ctx.beginPath();
      pathFor(ctx, node);
      ctx.clip();
    }
    for (const cid of node.children) {
      const child = doc.nodes[cid];
      if (child && child.visible) drawNode(ctx, doc, child, zoom);
    }
  }

  ctx.filter = "none";
  ctx.restore();
}

function pathFor(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  ctx.beginPath();
  switch (node.type) {
    case "ellipse":
      ctx.ellipse(node.width / 2, node.height / 2, node.width / 2, node.height / 2, 0, 0, Math.PI * 2);
      break;
    case "polygon": {
      const pts = regularPolygon(node.sides, node.width, node.height);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      ctx.closePath();
      break;
    }
    case "star": {
      const pts = starPolygon(node.points, node.innerRatio, node.width, node.height);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      ctx.closePath();
      break;
    }
    case "path": {
      const pts = flattenPath(node.points, node.closed);
      pts.forEach((p, i) => (i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y)));
      if (node.closed) ctx.closePath();
      break;
    }
    case "line":
      ctx.moveTo(0, node.height / 2);
      ctx.lineTo(node.width, node.height / 2);
      break;
    default: {
      const r =
        "cornerRadius" in node
          ? node.cornerRadius
          : { tl: 0, tr: 0, br: 0, bl: 0 };
      roundRectPath(ctx, 0, 0, node.width, node.height, r);
    }
  }
}

function fillShape(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  if (node.type === "line" || node.type === "text" || node.fills.length === 0) return;
  for (const paint of node.fills) {
    pathFor(ctx, node);
    ctx.fillStyle = applyPaint(ctx, paint, node.width, node.height);
    ctx.fill();
  }
}

function strokeShape(ctx: CanvasRenderingContext2D, node: SceneNode): void {
  for (const stroke of node.strokes) {
    const o = strokeOffset(stroke, node.width, node.height);
    ctx.save();
    ctx.translate(o.x, o.y);
    ctx.scale(o.w / node.width || 1, o.h / node.height || 1);
    pathFor(ctx, node);
    ctx.strokeStyle = applyPaint(ctx, stroke.paint, node.width, node.height);
    ctx.lineWidth = stroke.thickness * (node.width / (o.w || 1));
    ctx.lineCap = stroke.cap;
    ctx.lineJoin = stroke.join;
    ctx.setLineDash(stroke.dash);
    ctx.stroke();
    ctx.restore();
  }
}

function drawText(ctx: CanvasRenderingContext2D, node: Extract<SceneNode, { type: "text" }>): void {
  const t = node.text;
  ctx.font = fontCss(t);
  ctx.fillStyle = colorToCss(t.color);
  ctx.textBaseline = "alphabetic";
  const lines = wrapLines(node.characters, node.width, t.letterSpacing, (s) => ctx.measureText(s).width);
  const lh = t.fontSize * t.lineHeight;
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, node.width, node.height);
  ctx.clip();
  lines.forEach((line, i) => {
    const x = lineOffsetX(t.align, line.width, node.width);
    const y = (i + 0.85) * lh;
    if (t.letterSpacing === 0) {
      ctx.fillText(line.text, x, y);
    } else {
      let cx = x;
      for (const ch of line.text) {
        ctx.fillText(ch, cx, y);
        cx += ctx.measureText(ch).width + t.letterSpacing;
      }
    }
  });
  ctx.restore();
}

function drawImage(ctx: CanvasRenderingContext2D, node: Extract<SceneNode, { type: "image" }>): void {
  const img = preloadImage(node.src);
  pathFor(ctx, node);
  ctx.save();
  ctx.clip();
  if (!img) {
    ctx.fillStyle = "#3a3a3a";
    ctx.fillRect(0, 0, node.width, node.height);
    ctx.restore();
    return;
  }
  const iw = img.naturalWidth || img.width;
  const ih = img.naturalHeight || img.height;
  if (node.fit === "fill") {
    ctx.drawImage(img, 0, 0, node.width, node.height);
  } else {
    const scale =
