import { booleanPolygons, polygonAABB, type BooleanOp } from "./boolean";
import {
  applyPatch,
  cmdAddPage,
  cmdAlign,
  cmdBringForward,
  cmdBringToFront,
  cmdDelete,
  cmdDuplicate,
  cmdGroup,
  cmdInsertNodes,
  cmdRename,
  cmdReorder,
  cmdSendBackward,
  cmdSendToBack,
  cmdSetColorStyles,
  cmdSetComments,
  cmdSetLinks,
  cmdSetName,
  cmdSetProps,
  cmdToggleLocked,
  cmdToggleVisible,
  cmdUngroup,
  cmdUpdateNodes,
  emptyHistory,
  pushHistory,
  type Command,
  type History,
} from "./commands";
import { BLACK, cloneColor, rgb } from "./color";
import { createBlankDocument } from "./demo-document";
import {
  createEllipse,
  createFrame,
  createGroup,
  createImage,
  createLine,
  createPage,
