} from "./factories";
import { apply, nodeLocalMatrix } from "./geometry";
import { nid } from "./ids";
import {
  checkpoint,
  deleteDocument,
  duplicateDocument,
  loadIndex,
  loadLastOrDemo,
  loadVersions,
  newUntitled,
  parseDocument,
  restoreVersion,
  saveDocument,
  serializeDocument,
  type VersionSnapshot,
} from "./persistence";
import {
  activePage,
  allNodeIds,
  selectionAABB,
  shapePolygon,
  topLevelSelection,
  worldAABB,
} from "./scene";
import { SpatialIndex } from "./spatial-index";
import type {
  AABB,
  Camera,
  Color,
  Document,
  DocumentMeta,
  Guide,
  NodeId,
  PageId,
  PathPoint,
  SceneNode,
  Tool,
