+      return;
+    }
+  }
+
+  const hit = pickTopNode(doc, world, st.camera.zoom, { ignoreLocked: true });
+  if (hit) {
+    if (mods.shift) setSelection([hit], true);
+    else if (!st.selection.includes(hit)) setSelection([hit]);
