+}
+
+export function endPointer(gesture: { current: Gesture }, shift: boolean): void {
+  const g = gesture.current;
+  gesture.current = { kind: "none" };
+  const st = getState();
+  if (g.kind === "pan") {
+    setCamera(st.camera);
+    return;
+  }
+  if (g.kind === "marquee") {
+    const m = st.marquee;
