          downloadText(`${doc.name}.svg`, exportSvg(doc, getState().selection, (font, text) => {
            if (!ctx) return text.length * 7;
            ctx.font = font;
            return ctx.measureText(text).width;
          }), "image/svg+xml");
        }}
      >
        SVG
      </button>
    </div>
  );
}

