import { useEffect, useMemo, useState } from "react";
import { SHORTCUTS } from "../input/shortcuts";
import {
  addPage,
  booleanSelection,
  groupSelection,
  newFile,
  patchUi,
  seedStress,
  setTool,
} from "../core/store";
import { useEditor } from "./use-editor";

export function CommandPalette() {
  const open = useEditor((s) => s.ui.paletteOpen);
  const [q, setQ] = useState("");
  const items = useMemo(() => {
    const all = [
      { label: "Move tool", run: () => setTool("select") },
      { label: "Frame tool", run: () => setTool("frame") },
      { label: "Rectangle", run: () => setTool("rectangle") },
      { label: "Ellipse", run: () => setTool("ellipse") },
      { label: "Text", run: () => setTool("text") },
      { label: "Pen", run: () => setTool("pen") },
      { label: "Group selection", run: () => groupSelection() },
      { label: "New page", run: () => addPage() },
      { label: "New file", run: () => newFile() },
      { label: "Boolean union", run: () => booleanSelection("union") },
      { label: "Insert 1000 rectangles", run: () => seedStress(1000) },
      { label: "Play prototype", run: () => patchUi({ playMode: true }) },
    ];
    const qq = q.toLowerCase();
    return all.filter((i) => i.label.toLowerCase().includes(qq));
  }, [q]);
  if (!open) return null;
  return (
    <div className="modal-backdrop" onClick={() => patchUi({ paletteOpen: false })}>
      <div className="palette" onClick={(e) => e.stopPropagation()}>
        <input autoFocus placeholder="Run a command" value={q} onChange={(e) => setQ(e.target.value)} />
        {items.map((i) => (
          <button
            key={i.label}
            className="palette-item"
            onClick={() => {
              i.run();
              patchUi({ paletteOpen: false });
            }}
          >
            {i.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function ShortcutHelp() {
  const open = useEditor((s) => s.ui.helpOpen);
  useEffect(() => undefined, []);
  if (!open) return null;
  return (
    <div className="modal-backdrop" onClick={() => patchUi({ helpOpen: false })}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <h2>Shortcuts</h2>
        {SHORTCUTS.map((s) => (
          <div className="shortcut-row" key={s.label}>
            <span>{s.label}</span>
            <kbd>{s.keys}</kbd>
          </div>
        ))}
      </div>
    </div>
  );
}

import { worldAABB } from "../core/scene";
import { patchUi, viewDocument } from "../core/store";
import { useEditor } from "./use-editor";

export function PlayMode() {
  const open = useEditor((s) => s.ui.playMode);
  const doc = useEditor((s) => s.document);
  const startId = useEditor((s) => s.ui.playFrameId);
  if (!open) return null;
  const frames = Object.values(doc.nodes).filter((n) => n.type === "frame");
  const current = (startId && doc.nodes[startId]) || frames[0];
  if (!current) {
    return (
      <div className="play-root">
        <button className="play-close" onClick={() => patchUi({ playMode: false })}>Exit</button>
        <div className="empty">No frames to play.</div>
      </div>
    );
  }
  const b = worldAABB(viewDocument(), current.id);
  const links = doc.prototypeLinks.filter((l) => l.fromId === current.id || ancestorHas(current.id, l.fromId));
  return (
    <div className="play-root">
      <button className="play-close" onClick={() => patchUi({ playMode: false, playFrameId: null })}>Exit play</button>
      <div
        className="play-frame"
        style={{ width: Math.min(390, current.width), height: Math.min(844, current.height), background: "#fff" }}
      >
        <PlayCanvas nodeId={current.id} />
        {links.map((l) => (
          <button
            key={l.id}
            className="btn primary"
            style={{ position: "absolute", bottom: 16, left: 16, right: 16 }}
            onClick={() => patchUi({ playFrameId: l.toId })}
          >
            Next
          </button>
        ))}
      </div>
      <span style={{ display: "none" }}>{b.minX}</span>
    </div>
  );
}

function ancestorHas(frameId: string, fromId: string): boolean {
  const doc = viewDocument();
  let cur = doc.nodes[fromId];
  while (cur) {
    if (cur.id === frameId) return true;
    if (!cur.parentId) break;
    cur = doc.nodes[cur.parentId];
  }
  return false;
}

function PlayCanvas({ nodeId }: { nodeId: string }) {
  const doc = viewDocument();
  const node = doc.nodes[nodeId];
  if (!node) return null;
  return (
    <div style={{ width: node.width, height: node.height, transform: `scale(${Math.min(1, 390 / node.width)})`, transformOrigin: "top left" }}>
      <div style={{ padding: 24, fontFamily: "Inter, system-ui" }}>
        <strong>{node.name}</strong>
        <p>Click Next to follow prototype links.</p>
      </div>
    </div>
  );
}

