:root {
  --bg: oklch(0.2 0.012 270);
  --panel: oklch(0.235 0.012 270);
  --elev: oklch(0.28 0.012 270);
  --line: oklch(0.34 0.01 270);
  --ink: oklch(0.93 0.01 270);
  --muted: oklch(0.68 0.02 270);
  --accent: oklch(0.68 0.14 245);
  --accent-ink: oklch(0.98 0.02 245);
  --danger: oklch(0.65 0.18 25);
  --guide: oklch(0.7 0.28 350);
  --focus: oklch(0.72 0.14 245);
  --radius: 6px;
  --font: Inter, system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, monospace;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body, #root { height: 100%; margin: 0; }
body {
  font-family: var(--font);
  font-size: 12px;
  color: var(--ink);
  background: var(--bg);
  overflow: hidden;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}
button {
  background: transparent;
  border: 0;
  cursor: pointer;
}
button:disabled { opacity: 0.4; cursor: default; }
button:focus-visible, input:focus-visible, select:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 1px;
}

.app {
  display: grid;
  grid-template-rows: 44px 1fr 28px;
  height: 100%;
}
.workspace {
  display: grid;
  grid-template-columns: auto 1fr auto;
  min-height: 0;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 10px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
}
.brand {
  font-weight: 600;
  font-size: 13px;
  letter-spacing: -0.02em;
  padding: 0 8px;
  white-space: nowrap;
}
.file-name {
  background: var(--elev);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 4px 8px;
  min-width: 140px;
}
.topbar-actions { margin-left: auto; display: flex; gap: 6px; align-items: center; }
.zoom-readout {
  font-variant-numeric: tabular-nums;
  color: var(--muted);
  min-width: 48px;
  text-align: right;
}

.toolbar {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 6px;
  background: var(--panel);
  border-right: 1px solid var(--line);
  width: 44px;
}
.tool {
  width: 32px;
  height: 32px;
  border-radius: 6px;
  color: var(--muted);
  display: grid;
  place-items: center;
}
.tool:hover { background: var(--elev); color: var(--ink); }
.tool.active { background: var(--elev); color: var(--accent); }

.panel {
  width: 260px;
  background: var(--panel);
  border-left: 1px solid var(--line);
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.panel.left { border-left: 0; border-right: 1px solid var(--line); }
.panel-head {
  padding: 10px 12px 8px;
  font-weight: 600;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.panel-body { overflow: auto; padding: 0 8px 16px; flex: 1; }
.search {
  width: 100%;
  background: var(--elev);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 6px 8px;
  margin-bottom: 8px;
}

.layer {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 3px 4px;
  border-radius: 4px;
  user-select: none;
}
.layer:hover { background: var(--elev); }
.layer.selected { background: color-mix(in oklch, var(--accent) 22%, var(--panel)); }
.layer-name { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.icon-btn {
  width: 22px;
  height: 22px;
  border-radius: 4px;
  color: var(--muted);
}
.icon-btn:hover { background: var(--elev); color: var(--ink); }

.section { margin-top: 12px; }
.section-title {
  color: var(--muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.row { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-bottom: 6px; }
.row3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; margin-bottom: 6px; }
.field { display: flex; flex-direction: column; gap: 3px; }
.field label { color: var(--muted); font-size: 10px; }
.field input, .field select {
  background: var(--elev);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 5px 6px;
  width: 100%;
}
.swatch {
  width: 100%;
  height: 28px;
  border-radius: 4px;
  border: 1px solid var(--line);
  cursor: pointer;
}
.btn {
  background: var(--elev);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 6px 8px;
}
.btn:hover { border-color: color-mix(in oklch, var(--accent) 40%, var(--line)); }
.btn.primary { background: var(--accent); color: #0b1220; border-color: transparent; font-weight: 600; }
.btn.danger { color: var(--danger); }
.align-row { display: flex; gap: 2px; flex-wrap: wrap; }

.statusbar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  background: var(--panel);
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}
.statusbar strong { color: var(--ink); font-weight: 500; }

.canvas-wrap {
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #2c2c2c;
}
.canvas-scene, .canvas-overlay {
  position: absolute;
  inset: 0;
  display: block;
}
.canvas-overlay { pointer-events: none; }
.text-editor {
  position: absolute;
  left: 80px;
  top: 80px;
  min-width: 200px;
  min-height: 40px;
  background: #fff;
  color: #111;
  border: 1px solid var(--accent);
  padding: 4px 6px;
  z-index: 4;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 0.45);
  display: grid;
  place-items: center;
  z-index: 20;
}
.modal {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  width: min(480px, calc(100vw - 32px));
  max-height: min(70vh, 560px);
  overflow: auto;
  padding: 16px;
}
.modal h2 { margin: 0 0 12px; font-size: 16px; }
.shortcut-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 6px 0;
  border-bottom: 1px solid var(--line);
}
kbd {
  font-family: var(--mono);
  font-size: 11px;
  background: var(--elev);
  padding: 2px 6px;
  border-radius: 4px;
