  if (!s) return "";
  const dash = s.dash.length ? ` stroke-dasharray="${s.dash.join(" ")}"` : "";
  return `stroke="${paintToSvg(s.paint, "s")}" stroke-width="${s.thickness}"${dash}`;
}

