  const orb = createEllipse({
    name: "Lamp orb",
    parentId: desktop.id,
    x: 820,
    y: 160,
    width: 320,
    height: 320,
    fills: [
      linearPaint(
        [
          { offset: 0, color: rgb(232, 196, 140) },
          { offset: 1, color: rgb(201, 132, 76) },
        ],
        { x: 0.3, y: 0.2 },
        { x: 0.8, y: 0.9 },
      ),
    ],
    effects: [dropShadow(0, 40, 80, 0.45)],
  });
  const ring = createEllipse({
    name: "Halo",
    parentId: desktop.id,
    x: 780,
    y: 120,
    width: 400,
    height: 400,
    fills: [],
    strokes: [
      {
        paint: solid(rgb(232, 196, 140), 0.35),
        thickness: 1,
        align: "center",
        cap: "butt",
        join: "miter",
        dash: [6, 8],
      },
    ],
  });

  desktop.children = [deskNav.id, deskBrand.id, deskHero.id, deskCopy.id, ring.id, orb.id];

  const put = (...list: { id: string }[]) => {
    for (const n of list) nodes[n.id] = n as Document["nodes"][string];
  };

  put(
    phone,
    status,
    time,
    battery,
    hero,
    kicker,
    title,
    subtitle,
    body,
    c1,
    c2,
    c3,
    buttonMaster,
    btnLabel,
    btnInstance,
    desktop,
    deskNav,
    deskBrand,
    deskHero,
    deskCopy,
    orb,
    ring,
  );

  page.children = [phone.id, buttonMaster.id, desktop.id];

  return {
    id: nid("doc"),
    name: "Northlight",
    pages: [page],
    activePageId: page.id,
    nodes,
    colorStyles: [
