      { id: nid("style"), name: "Paper", paint: solid(rgb(246, 245, 242)) },
      { id: nid("style"), name: "Copper", paint: solid(rgb(201, 132, 76)) },
      { id: nid("style"), name: "Night", paint: solid(rgb(36, 48, 64)) },
    ],
    textStyles: [
      {
        id: nid("style"),
        name: "Display",
        text: {
          fontFamily: "Playfair Display",
          fontWeight: 600,
          fontSize: 36,
          lineHeight: 1.1,
          letterSpacing: -0.4,
          align: "left",
          color: BLACK,
        },
      },
      {
        id: nid("style"),
        name: "Body",
        text: {
          fontFamily: "Inter",
          fontWeight: 400,
          fontSize: 14,
          lineHeight: 1.45,
          letterSpacing: 0,
          align: "left",
          color: rgb(90, 90, 96),
        },
      },
    ],
    prototypeLinks: [
      {
        id: nid("link"),
        fromId: btnInstance.id,
        toId: desktop.id,
        animation: "dissolve",
      },
    ],
    comments: [
      {
        id: nid("c"),
        x: 200,
        y: 300,
        resolved: false,
        messages: [
          {
            id: nid("m"),
            author: "You",
            body: "Try a slightly cooler hero so the copper cards pop.",
            createdAt: Date.now() - 3600_000,
          },
        ],
      },
    ],
    schema: 1,
  };
}

export function createBlankDocument(): Document {
  const page = createPage("Page 1");
  return {
    id: nid("doc"),
    name: "Untitled",
    pages: [page],
    activePageId: page.id,
    nodes: {},
    colorStyles: [],
    textStyles: [],
    prototypeLinks: [],
    comments: [],
    schema: 1,
  };
}

void color;
void createEllipse;

