    const c = worldToScreen(b.maxX, b.maxY, camera, view.width, view.height, true);
    ctx.fillRect(a.x, 0, Math.max(1, c.x - a.x), r);
    ctx.fillRect(0, a.y, r, Math.max(1, c.y - a.y));
